import { initializeApp, getApps, getApp } from "firebase/app";
import {
  getFirestore,
  collection,
  addDoc,
  getDocs,
  query,
  where,
  onSnapshot,
  doc,
  updateDoc,
  deleteDoc,
  serverTimestamp
} from "firebase/firestore";

// Firebase Config - Geliştirme ortamı
const firebaseConfig = {
  apiKey: process.env.REACT_APP_FIREBASE_API_KEY,
  authDomain: process.env.REACT_APP_FIREBASE_AUTH_DOMAIN,
  projectId: process.env.REACT_APP_FIREBASE_PROJECT_ID,
  storageBucket: process.env.REACT_APP_FIREBASE_STORAGE_BUCKET,
  messagingSenderId: process.env.REACT_APP_FIREBASE_MESSAGING_SENDER_ID,
  appId: process.env.REACT_APP_FIREBASE_APP_ID
};

// Geliştirme ortamında varsayılan config
if (!process.env.REACT_APP_FIREBASE_API_KEY) {
  console.warn("⚠️ Firebase Config yok! Demo modunda çalışılıyor.");
  console.warn("Lütfen .env dosyası oluşturun:");
  console.warn("REACT_APP_FIREBASE_API_KEY=your-api-key");
}

// Firebase başlat
const app = !getApps().length ? initializeApp(firebaseConfig) : getApp();
const db = getFirestore(app);

// Collection Ref'ler
export const ilanlarRef = collection(db, "ilanlar");
export const seferlerRef = collection(db, "seferler");
export const kullanicilarRef = collection(db, "kullanicilar");
export const konusmalarRef = collection(db, "konusmalar");
export const tekliflerRef = collection(db, "teklifler");

// Firestore Functions
export const ilanEkle = async (ilanVerisi) => {
  try {
    const yeniIlan = {
      ...ilanVerisi,
      olusturan: ilanVerisi.oturum?.ad || "Demo Firma",
      olusturanPuan: 5.0,
      olusturanId: ilanVerisi.oturum?.id || "demo",
      istekSayisi: 0,
      durum: "aktif",
      belgeler: [],
      odemeTuru: ilanVerisi.odemeTuru || "pesin",
      odemeGun: ilanVerisi.odemeGun || 0,
      kdvOrani: ilanVerisi.ucretTipi === "kdv" ? 0.20 : 0,
      kdvTutari: ilanVerisi.kdvTutari || 0,
      toplamUcret: ilanVerisi.toplamUcret || ilanVerisi.ucret,
      olusturmaZamani: serverTimestamp()
    };

    const docRef = await addDoc(ilanlarRef, yeniIlan);
    console.log("İlan eklendi:", docRef.id);
    return { id: docRef.id, ...yeniIlan };
  } catch (error) {
    console.error("İlan ekleme hatası:", error);
    throw error;
  }
};

export const ilanAl = async (ilanId, kamyoncuBilgileri, oturum) => {
  try {
    // İlanı güncelle
    const ilanDoc = doc(db, "ilanlar", ilanId);
    await updateDoc(ilanDoc, {
      durum: "alindi",
      istekSayisi: 0
    });

    // Yeni sefer ekle
    const yeniSefer = {
      yuk: ilanVerisi.yuk,
      nereden: ilanVerisi.nereden,
      nereye: ilanVerisi.nereye,
      ucret: ilanVerisi.ucret,
      tarih: ilanVerisi.tarih,
      sure: ilanVerisi.sure,
      ton: kamyoncuBilgileri.tonaj || 0,
      aracTip: ilanVerisi.aracTip,
      ilanId: ilanId,
      plaka: kamyoncuBilgileri.plaka,
      dorsePlaka: kamyoncuBilgileri.dorsePlaka,
      kamyoncu: kamyoncuBilgileri.ad,
      kamyoncuTel: kamyoncuBilgileri.tel,
      kamyoncuTC: kamyoncuBilgileri.tcKimlik,
      olusturan: ilanVerisi.olusturan,
      durum: "yolda",
      teslimTarihi: null,
      belgeler: [],
      odemeTarihi: null,
      odemeDurumu: "beklemede",
      odemeTuru: ilanVerisi.odemeTuru,
      odemeGun: ilanVerisi.odemeGun,
      iban: ilanVerisi.iban,
      ibanSahibi: ilanVerisi.ibanSahibi,
      olusturmaZamani: serverTimestamp()
    };

    const seferDocRef = await addDoc(seferlerRef, yeniSefer);
    return { id: seferDocRef.id, ...yeniSefer };
  } catch (error) {
    console.error("Sefer oluşturma hatası:", error);
    throw error;
  }
};

export const konusmaAc = async (konusmaVerisi) => {
  try {
    const yeniKonusma = {
      ...konusmaVerisi,
      partnerRol: konusmaVerisi.isTrucker ? "kamyoncu" : "issiz",
      partnerId: konusmaVerisi.partnerId,
      partnerAd: konusmaVerisi.partnerAd,
      isTrucker: konusmaVerisi.isTrucker,
      konusmaTuru: "is",
      resim: `https://api.dicebear.com/7.x/initials/svg?seed=${konusmaVerisi.partnerAd?.substring(0, 2).toUpperCase()}`,
      bg: "linear-gradient(135deg, #667eea 0%, #764ba2 100%)",
      mesajlar: [],
      okunmamis: 0,
      sonOkuma: Date.now(),
      sonGuncelleme: Date.now(),
      olusturmaZamani: serverTimestamp()
    };

    const docRef = await addDoc(konusmalarRef, yeniKonusma);
    console.log("Konuşma oluşturuldu:", docRef.id);
    return { id: docRef.id, ...yeniKonusma };
  } catch (error) {
    console.error("Konuşma oluşturma hatası:", error);
    throw error;
  }
};

export const mesajGonder = async (konusmaId, metin, veriTipi = "metin", veri = null) => {
  try {
    const konusmaDoc = doc(db, "konusmalar", konusmaId);

    const yeniMesaj = {
      id: Date.now(),
      gonderen: "ben",
      metin: metin,
      veriTipi: veriTipi,
      veri: veri,
      zaman: Date.now(),
      okunduZamani: null
    };

    const mesajlarCollection = collection(konusmaDoc, "mesajlar");
    await addDoc(mesajlarCollection, yeniMesaj);

    // Son okuma zamanını güncelle
    await updateDoc(konusmaDoc, {
      sonOkuma: Date.now()
    });
  } catch (error) {
    console.error("Mesaj gönderme hatası:", error);
    throw error;
  }
};

// Real-time listener
export const ilanlarGetir = (onData) => {
  return onSnapshot(
    query(ilanlarRef, where("durum", "==", "aktif")),
    (snapshot) => {
      const ilanlar = snapshot.docs.map(doc => ({
        id: doc.id,
        ...doc.data()
      }));
      onData(ilanlar);
    },
    (error) => console.error("İlanlar alınamadı:", error)
  );
};

export const seferleriGetir = (onData) => {
  return onSnapshot(
    seferlerRef,
    (snapshot) => {
      const seferler = snapshot.docs.map(doc => ({
        id: doc.id,
        ...doc.data()
      }));
      onData(seferler);
    },
    (error) => console.error("Seferler alınamadı:", error)
  );
};

export const konusmalariGetir = (onData) => {
  return onSnapshot(
    query(konusmalarRef, where("partnerRol", "!=", "admin")),
    (snapshot) => {
      const konusmalar = snapshot.docs.map(doc => ({
        id: doc.id,
        ...doc.data()
      }));
      onData(konusmalar);
    },
    (error) => console.error("Konusmalar alınamadı:", error)
  );
};

export default db;
